package com.termux.app.workspace;
import android.app.*;import android.graphics.Rect;import android.view.*;import android.widget.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class WorkspacePopoverTest {
 Activity a;WorkspacePopover menu;
 @Before public void setup(){a=Robolectric.buildActivity(Activity.class).setup().visible().get();}
 @After public void close(){if(menu!=null)menu.dismiss();a.finish();}
 private View anchor(int y){View v=new View(a){@Override public void getWindowVisibleDisplayFrame(Rect out){out.set(0,24,360,420);}@Override public void getLocationOnScreen(int[] xy){xy[0]=12;xy[1]=y;}};a.setContentView(v);return v;}
 private PopupWindow popup()throws Exception{java.lang.reflect.Field f=WorkspacePopover.class.getDeclaredField("window");f.setAccessible(true);return (PopupWindow)f.get(menu);}
 @Test public void constrainedMenuScrollsAboveAnchorAndSelectionRunsOnlyOnce()throws Exception{AtomicInteger selected=new AtomicInteger(),dismissed=new AtomicInteger();menu=new WorkspacePopover(a);for(String label:new String[]{"Фото из галереи","Файл с устройства","Файлы проекта","Другие окружения"})menu.item(label,com.termux.R.drawable.workspace_folder,selected::incrementAndGet);menu.dismissed(dismissed::incrementAndGet);menu.show(anchor(150));PopupWindow window=popup();assertTrue(menu.isShowing());assertEquals(0,selected.get());assertTrue(window.getHeight()<=150-24-WorkspaceDialogs.dp(a,14));assertEquals(PopupWindow.INPUT_METHOD_NOT_NEEDED,window.getInputMethodMode());assertEquals(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING|WindowManager.LayoutParams.SOFT_INPUT_STATE_UNCHANGED,window.getSoftInputMode());ScrollView scroll=(ScrollView)window.getContentView();LinearLayout items=(LinearLayout)scroll.getChildAt(0);assertEquals(4,items.getChildCount());for(int i=0;i<4;i++)assertNotNull(((TextView)items.getChildAt(i)).getCompoundDrawables()[0]);items.getChildAt(3).performClick();assertEquals(1,selected.get());assertEquals(1,dismissed.get());assertFalse(menu.isShowing());}
 @Test public void belowMenuRetainsItsOwnCallbacksWithoutAutomaticMutation()throws Exception{AtomicInteger selected=new AtomicInteger();menu=new WorkspacePopover(a);menu.item("Save",com.termux.R.drawable.workspace_save,selected::incrementAndGet);menu.item("Close",com.termux.R.drawable.workspace_delete,()->selected.addAndGet(10));menu.showBelow(anchor(70));assertTrue(menu.isShowing());assertEquals(0,selected.get());LinearLayout items=(LinearLayout)((ScrollView)popup().getContentView()).getChildAt(0);items.getChildAt(0).performClick();assertEquals(1,selected.get());assertFalse(menu.isShowing());}
 @Test public void noSpaceAndDismissDoNotRunActionsAndAllowReopen(){AtomicInteger selected=new AtomicInteger(),dismissed=new AtomicInteger();menu=new WorkspacePopover(a);menu.item("File",0,selected::incrementAndGet);menu.dismissed(dismissed::incrementAndGet);menu.show(anchor(24));assertFalse(menu.isShowing());assertEquals(1,dismissed.get());menu.show(anchor(400));assertTrue(menu.isShowing());menu.dismiss();assertEquals(2,dismissed.get());assertEquals(0,selected.get());menu.show(anchor(400));assertTrue(menu.isShowing());menu.dismiss();assertEquals(3,dismissed.get());}
}
